import { Ionicons } from "@expo/vector-icons";
import { LinearGradient } from "expo-linear-gradient";
import type { ReactNode } from "react";
import { Pressable, ScrollView, View } from "react-native";

import { SvgIcon } from "@/components/ui/svg-icon";

import { FORMAT_TOOLS, MEDIA_TOOLS } from "./constants";

function IconButton({
  children,
  onPress,
}: {
  children: ReactNode;
  onPress?: () => void;
}) {
  return (
    <Pressable
      className="h-10 w-10 items-center justify-center rounded-[8px] bg-channel-active-bg"
      onPress={onPress}
    >
      {children}
    </Pressable>
  );
}

export function ComposerToolbar({
  onMediaToolPress,
  onFormatPress,
  onAddPost,
  onReset,
  bottomInset,
  disabled = false,
  showReset = false,
}: {
  onMediaToolPress: (toolId: string) => void;
  onFormatPress: (toolId: string) => void;
  onAddPost: () => void;
  onReset?: () => void;
  bottomInset: number;
  disabled?: boolean;
  showReset?: boolean;
}) {
  const dim = 0.35;

  return (
    <View
      className="bg-background-primary"
      style={{ paddingBottom: bottomInset > 0 ? bottomInset : 0 }}
    >
      <View className="flex-row items-center gap-5 px-4 pt-2 pb-2">
        <View className="relative flex-1 overflow-hidden">
          <ScrollView
            horizontal
            showsHorizontalScrollIndicator={false}
            keyboardShouldPersistTaps="handled"
            contentContainerClassName="items-center gap-1 pr-[66px]"
          >
            {MEDIA_TOOLS.map((tool, index) =>
              index === 0 ? (
                <IconButton
                  key={tool.id}
                  onPress={
                    disabled ? undefined : () => onMediaToolPress(tool.id)
                  }
                >
                  <SvgIcon
                    source={tool.icon}
                    size={20}
                    opacity={disabled ? dim : 1}
                  />
                </IconButton>
              ) : (
                <IconButton key={tool.id}>
                  <SvgIcon source={tool.icon} size={20} opacity={dim} />
                </IconButton>
              ),
            )}

            <View className="mx-2 h-[15px] w-px bg-separator-primary" />

            <IconButton>
              <SvgIcon
                source={require("@/assets/icons/create-post/toolbar-signature.svg")}
                size={20}
                opacity={dim}
              />
            </IconButton>

            {FORMAT_TOOLS.map((tool) => (
              <IconButton
                key={tool.id}
                onPress={disabled ? undefined : () => onFormatPress(tool.id)}
              >
                <SvgIcon
                  source={tool.icon}
                  size={16}
                  opacity={disabled ? dim : 1}
                />
              </IconButton>
            ))}

            <IconButton
              onPress={disabled ? undefined : () => onFormatPress("emoji")}
            >
              <Ionicons
                name="happy-outline"
                size={20}
                className="text-icon-primary"
                style={{ opacity: disabled ? dim : 1 }}
              />
            </IconButton>
          </ScrollView>

          <LinearGradient
            colors={["rgba(26,25,25,0)", "#1A1919"]}
            start={{ x: 0, y: 0.5 }}
            end={{ x: 1, y: 0.5 }}
            pointerEvents="none"
            style={{
              position: "absolute",
              right: 0,
              top: 0,
              height: 40,
              width: 66,
            }}
          />
        </View>

        <View className="flex-row items-center gap-2" style={{ flexShrink: 0 }}>
          {showReset ? (
            <Pressable
              className="h-10 w-10 items-center justify-center rounded-[8px] bg-buttons-tertiary-bg"
              onPress={onReset}
            >
              <SvgIcon
                source={require("@/assets/icons/create-post/toolbar-refresh-ccw.svg")}
                size={20}
              />
            </Pressable>
          ) : null}

          <Pressable
            className={`h-10 w-10 items-center justify-center rounded-[8px] ${
              disabled ? "bg-[#3C3C3C]" : "bg-buttons-secondary-bg"
            }`}
            onPress={onAddPost}
            disabled={disabled}
          >
            <SvgIcon
              source={require("@/assets/icons/create-post/plus.svg")}
              size={20}
              tintColor={disabled ? "#9E9E9E" : undefined}
            />
          </Pressable>
        </View>
      </View>
    </View>
  );
}

import { forwardRef, useCallback, useRef, useState } from "react";
import type { ReactNode } from "react";
import { Platform, Pressable, Text, TextInput, View } from "react-native";
import type { TextInputProps } from "react-native";

type AuthInputProps = {
  label: string;
  hint?: string;
  error?: boolean;
  rightSlot?: ReactNode;
} & TextInputProps;

export const AuthInput = forwardRef<TextInput, AuthInputProps>(
  function AuthInput(
    {
      label,
      hint,
      error = false,
      rightSlot,
      secureTextEntry,
      onFocus,
      onBlur,
      ...textInputProps
    },
    ref
  ) {
    const internalRef = useRef<TextInput>(null);
    const [focused, setFocused] = useState(false);

    const setRef = useCallback(
      (node: TextInput | null) => {
        internalRef.current = node;
        if (typeof ref === "function") ref(node);
        else if (ref) (ref as React.RefObject<TextInput | null>).current = node;
      },
      [ref]
    );

    const handleFocus: TextInputProps["onFocus"] = (e) => {
      setFocused(true);
      onFocus?.(e);
    };

    const handleBlur: TextInputProps["onBlur"] = (e) => {
      setFocused(false);
      onBlur?.(e);
    };

    const handlePressField = () => {
      internalRef.current?.focus();
    };
    const shouldUseIosSecureWorkaround =
      Platform.OS === "ios" && !!secureTextEntry;
    const value =
      typeof textInputProps.value === "string" ? textInputProps.value : "";

    const borderClass = error
      ? "border-[#F87171]"
      : focused
      ? "border-[#7C3AED]"
      : "border-[#3A3838]";

    return (
      <View className="gap-2">
        <Text className="font-jakarta text-[14px] font-semibold leading-[14px] text-text-primary">
          {label}
        </Text>
        <Pressable
          onPress={handlePressField}
          className={`h-[52px] flex-row items-center gap-2 overflow-hidden rounded-[10px] border bg-[#1E1D1D] py-1 pl-4 pr-3 ${borderClass}`}
        >
          <View className="relative flex-1 self-stretch justify-center">
            <TextInput
              ref={setRef}
              className={`flex-1 text-text-primary ${secureTextEntry ? "text-[14px]" : "font-jakarta text-body-1"} ${shouldUseIosSecureWorkaround ? "text-transparent" : ""}`}
              placeholderTextColor="#A3A3A3"
              secureTextEntry={shouldUseIosSecureWorkaround ? false : secureTextEntry}
              autoCorrect={false}
              autoCapitalize="none"
              onFocus={handleFocus}
              onBlur={handleBlur}
              rejectResponderTermination={false}
              selectionColor="#7C3AED"
              {...textInputProps}
            />
            {shouldUseIosSecureWorkaround ? (
              <View pointerEvents="none" className="absolute inset-0 justify-center">
                <Text
                  numberOfLines={1}
                  className="text-text-primary text-[14px]"
                  style={{ includeFontPadding: false }}
                >
                  {"•".repeat(value.length)}
                </Text>
              </View>
            ) : null}
          </View>
          {rightSlot}
        </Pressable>
        {hint ? (
          <Text className="font-jakarta text-xs font-medium leading-3 text-text-critical">
            {hint}
          </Text>
        ) : null}
      </View>
    );
  }
);

import { Ionicons } from "@expo/vector-icons";
import { Image } from "expo-image";
import { useLocalSearchParams, useRouter } from "expo-router";
import { StatusBar } from "expo-status-bar";
import { useRef, useState } from "react";
import {
  Pressable,
  ScrollView,
  Text,
  TextInput,
  View,
} from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";

import { AppButton } from "@/components/ui/app-button";

const CODE_LENGTH = 5;

export default function VerifyOtpScreen() {
  const router = useRouter();
  const params = useLocalSearchParams<{ flow?: string }>();
  const isSignup = params.flow === "signup";
  const [code, setCode] = useState<string[]>(Array(CODE_LENGTH).fill(""));
  const [focusedIndex, setFocusedIndex] = useState<number | null>(null);
  const [error, setError] = useState<string | null>(null);
  const inputRefs = useRef<(TextInput | null)[]>([]);
  const fullCode = code.join("");
  const isCodeComplete = fullCode.length === CODE_LENGTH;
  const canVerify = isCodeComplete && !error;

  const handleChange = (text: string, index: number) => {
    if (error) setError(null);

    const digit = text.replace(/[^0-9]/g, "").slice(-1);
    const newCode = [...code];
    newCode[index] = digit;
    setCode(newCode);

    if (digit && index < CODE_LENGTH - 1) {
      inputRefs.current[index + 1]?.focus();
    }
  };

  const handleKeyPress = (key: string, index: number) => {
    if (key === "Backspace" && !code[index] && index > 0) {
      inputRefs.current[index - 1]?.focus();
      const newCode = [...code];
      newCode[index - 1] = "";
      setCode(newCode);
    }
  };

  const handleVerify = () => {
    if (!isCodeComplete) {
      return;
    }
    if (fullCode !== "11111") {
      setError("Incorrect code");
      return;
    }
    if (isSignup) {
      router.replace("/(auth)");
    } else {
      router.push("/(auth)/reset-password" as any);
    }
  };

  const handleResend = () => {
    setCode(Array(CODE_LENGTH).fill(""));
    setError(null);
    inputRefs.current[0]?.focus();
  };

  return (
    <SafeAreaView
      className="flex-1 bg-background-primary"
      edges={["top", "bottom"]}
    >
      <StatusBar style="light" />
      <ScrollView
        className="flex-1 bg-background-primary px-5 pt-12 pb-[20px]"
        contentContainerClassName="flex-grow"
        keyboardShouldPersistTaps="handled"
        showsVerticalScrollIndicator={false}
        automaticallyAdjustKeyboardInsets
      >
          <View className="mb-6 h-[27px] w-[84px]">
            <View className="absolute inset-0 right-[70.6%]">
              <Image
                source={require("@/assets/icons/login/postiz-mark.svg")}
                className="w-[25px] h-[27px]"
                contentFit="contain"
              />
            </View>
            <View className="absolute top-[1.61%] bottom-[10.76%] left-[37.32%] right-0">
              <Image
                source={require("@/assets/icons/login/postiz-wordmark.svg")}
                className="w-[53px] h-[24px]"
                contentFit="contain"
              />
            </View>
          </View>

          <View className="mb-6 w-full">
            <Pressable
              className="h-6 w-6 items-center justify-center"
              onPress={() => router.back()}
            >
              <Ionicons name="chevron-back" size={20} className="text-icon-primary" />
            </Pressable>
          </View>

          <View className="gap-8">
            <View className="gap-3">
              <Text className="font-jakarta text-2xl font-semibold leading-8 text-text-primary">
                Verify your account
              </Text>
              <Text className="font-jakarta text-sm text-text-secondary">
                Enter the 5-digit code sent to your email
              </Text>
            </View>

            <View className="gap-1">
              <View className="w-full flex-row justify-between">
                {code.map((digit, index) => (
                  <View
                    key={index}
                    className={`h-[52px] w-[56px] items-center justify-center overflow-hidden rounded-[10px] border ${
                      error
                        ? "border-text-critical"
                        : focusedIndex === index
                          ? "border-input-stroke-active"
                          : "border-input-stroke-default"
                    } bg-input-bg px-3 py-[4px]`}
                  >
                    <TextInput
                      ref={(ref) => { inputRefs.current[index] = ref; }}
                      className={`h-full w-full p-0 text-center leading-[14px] font-jakarta text-body-1 font-normal ${error ? "text-text-critical" : "text-text-primary"}`}
                      style={{ includeFontPadding: false }}
                      value={digit}
                      onChangeText={(text) => handleChange(text, index)}
                      onKeyPress={({ nativeEvent }) => handleKeyPress(nativeEvent.key, index)}
                      onFocus={() => setFocusedIndex(index)}
                      onBlur={() => setFocusedIndex(null)}
                      keyboardType="number-pad"
                      maxLength={1}
                      selectTextOnFocus
                      selectionColor="#8A62FD"
                      showSoftInputOnFocus
                    />
                  </View>
                ))}
              </View>

              {error ? (
                <Text className="font-jakarta text-xs leading-3 text-text-critical">{error}</Text>
              ) : null}
            </View>

            <AppButton
              label="Verify"
              variant={canVerify ? "primary" : "disabled"}
              disabled={!canVerify}
              onPress={handleVerify}
            />

            <View className="flex-row items-center gap-2">
              <Text className="font-jakarta text-sm text-text-primary">
                Don&apos;t received code?
              </Text>
              <Pressable onPress={handleResend}>
                <Text className="font-jakarta text-[15px] font-semibold text-main-accent-pink">
                  Resend
                </Text>
              </Pressable>
            </View>
          </View>
      </ScrollView>
    </SafeAreaView>
  );
}

import { Ionicons } from "@expo/vector-icons";
import { Image } from "expo-image";
import { useRouter } from "expo-router";
import { StatusBar } from "expo-status-bar";
import { useRef, useState } from "react";
import { Platform, Pressable, ScrollView, Text, TextInput, View } from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";

import { AppButton } from "@/components/ui/app-button";
import { AuthInput } from "@/components/ui/auth-input";
import { showToast } from "@/components/ui/toast";

function PasswordVisibilityToggle({
  visible,
  onPress,
}: {
  visible: boolean;
  onPress: () => void;
}) {
  return (
    <Pressable
      onPress={onPress}
    >
      {visible ? (
        <Ionicons name="eye-outline" size={20} className="text-icon-secondary" />
      ) : (
        <Image
          source={require("@/assets/icons/login/eye-slash.svg")}
          className="h-5 w-5"
          contentFit="contain"
        />
      )}
    </Pressable>
  );
}

export default function ResetPasswordScreen() {
  const router = useRouter();
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [passwordVisible, setPasswordVisible] = useState(false);
  const [confirmPasswordVisible, setConfirmPasswordVisible] = useState(false);
  const [focusedField, setFocusedField] = useState<"password" | "confirmPassword" | null>(null);
  const [errors, setErrors] = useState<{ password?: string; confirmPassword?: string }>({});
  const passwordInputRef = useRef<TextInput>(null);
  const confirmPasswordInputRef = useRef<TextInput>(null);

  const handleTogglePassword = () => {
    const wasFocused = passwordInputRef.current?.isFocused() ?? false;
    setPasswordVisible((prev) => !prev);
    if (wasFocused) {
      requestAnimationFrame(() => {
        passwordInputRef.current?.focus();
      });
    }
  };

  const handleToggleConfirmPassword = () => {
    const wasFocused = confirmPasswordInputRef.current?.isFocused() ?? false;
    setConfirmPasswordVisible((prev) => !prev);
    if (wasFocused) {
      requestAnimationFrame(() => {
        confirmPasswordInputRef.current?.focus();
      });
    }
  };

  const handleResetPassword = () => {
    const newErrors: { password?: string; confirmPassword?: string } = {};
    if (!password || password.length < 6) newErrors.password = "Password must be at least 6 characters";
    if (!confirmPassword) newErrors.confirmPassword = "Please confirm your password";
    else if (password !== confirmPassword) newErrors.confirmPassword = "Passwords do not match";
    setErrors(newErrors);
    if (Object.keys(newErrors).length > 0) return;

    showToast("Password reset successfully", "success");
    router.replace("/(auth)");
  };

  return (
    <SafeAreaView
      className="flex-1 bg-background-primary"
      edges={["top", "bottom"]}
    >
      <StatusBar style="light" />
      <ScrollView
        className="flex-1 bg-background-primary px-5 pt-12 pb-[20px]"
        contentContainerClassName="flex-grow"
        keyboardShouldPersistTaps="handled"
        showsVerticalScrollIndicator={false}
        automaticallyAdjustKeyboardInsets
      >
          <View className="mb-6 h-[27px] w-[84px]">
            <View className="absolute inset-0 right-[70.6%]">
              <Image
                source={require("@/assets/icons/login/postiz-mark.svg")}
                className="w-[25px] h-[27px]"
                contentFit="contain"
              />
            </View>
            <View className="absolute top-[1.61%] bottom-[10.76%] left-[37.32%] right-0">
              <Image
                source={require("@/assets/icons/login/postiz-wordmark.svg")}
                className="w-[53px] h-[24px]"
                contentFit="contain"
              />
            </View>
          </View>

          <View className="mb-6 w-full">
            <Pressable
              className="h-6 w-6 items-center justify-center"
              onPress={() => router.back()}
            >
              <Ionicons name="chevron-back" size={20} className="text-icon-primary" />
            </Pressable>
          </View>

          <View className="gap-8">
            <View className="gap-3">
              <Text className="font-jakarta text-2xl font-semibold leading-8 text-text-primary">
                Create New Password
              </Text>
              <Text className="font-jakarta text-sm text-text-secondary">
                Set a strong password to secure access.
              </Text>
            </View>

            <View className="gap-5">
              <AuthInput
                ref={passwordInputRef}
                label="Password"
                value={password}
                onChangeText={(text) => { setPassword(text); if (errors.password) setErrors((prev) => ({ ...prev, password: undefined })); }}
                placeholder="Enter password"
                secureTextEntry={!passwordVisible}
                textContentType="none"
                autoComplete="off"
                autoCapitalize="none"
                spellCheck={false}
                smartInsertDelete={false}
                keyboardType={Platform.OS === "ios" ? "ascii-capable" : "default"}
                onFocus={() => setFocusedField("password")}
                onBlur={() => setFocusedField(null)}
                error={!!errors.password}
                hint={errors.password}
                rightSlot={
                  <PasswordVisibilityToggle
                    visible={passwordVisible}
                    onPress={handleTogglePassword}
                  />
                }
              />

              <AuthInput
                ref={confirmPasswordInputRef}
                label="Confirm Password"
                value={confirmPassword}
                onChangeText={(text) => { setConfirmPassword(text); if (errors.confirmPassword) setErrors((prev) => ({ ...prev, confirmPassword: undefined })); }}
                placeholder="Confirm password"
                secureTextEntry={!confirmPasswordVisible}
                textContentType="none"
                autoComplete="off"
                autoCapitalize="none"
                spellCheck={false}
                smartInsertDelete={false}
                keyboardType={Platform.OS === "ios" ? "ascii-capable" : "default"}
                onFocus={() => setFocusedField("confirmPassword")}
                onBlur={() => setFocusedField(null)}
                error={!!errors.confirmPassword}
                hint={errors.confirmPassword}
                rightSlot={
                  <PasswordVisibilityToggle
                    visible={confirmPasswordVisible}
                    onPress={handleToggleConfirmPassword}
                  />
                }
              />
            </View>

            <AppButton label="Reset Password" onPress={handleResetPassword} />
          </View>
      </ScrollView>
    </SafeAreaView>
  );
}

import { Ionicons } from "@expo/vector-icons";
import { Image } from "expo-image";
import * as WebBrowser from "expo-web-browser";
import { useRouter } from "expo-router";
import { StatusBar } from "expo-status-bar";
import { useRef, useState } from "react";
import {
  Platform,
  Pressable,
  ScrollView,
  Text,
  TextInput,
  View,
} from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";

import { AppButton } from "@/components/ui/app-button";
import { AuthInput } from "@/components/ui/auth-input";

export default function SignUpScreen() {
  const router = useRouter();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [company, setCompany] = useState("");
  const [passwordVisible, setPasswordVisible] = useState(false);
  const [errors, setErrors] = useState<{
    email?: string;
    password?: string;
    company?: string;
  }>({});
  const passwordInputRef = useRef<TextInput>(null);

  const handleTogglePassword = () => {
    const wasFocused = passwordInputRef.current?.isFocused() ?? false;
    setPasswordVisible((prev) => !prev);
    if (wasFocused) {
      requestAnimationFrame(() => {
        passwordInputRef.current?.focus();
      });
    }
  };

  const handleCreateAccount = () => {
    const newErrors: { email?: string; password?: string; company?: string } =
      {};
    if (!email || !email.includes("@")) newErrors.email = "Incorrect email";
    if (!password || password.length < 6)
      newErrors.password = "Incorrect password";
    if (!company) newErrors.company = "Company name is required";
    setErrors(newErrors);
    if (Object.keys(newErrors).length === 0) {
      router.push({ pathname: "/(auth)/verify-otp", params: { email, flow: "signup" } } as any);
    }
  };

  return (
    <SafeAreaView
      className="flex-1 bg-background-primary"
      edges={["top", "bottom"]}
    >
      <StatusBar style="light" />
      <ScrollView
        className="flex-1 bg-background-primary"
        contentContainerClassName="flex-grow px-5 pt-12 pb-[20px]"
        keyboardShouldPersistTaps="handled"
        showsVerticalScrollIndicator={false}
        automaticallyAdjustKeyboardInsets
      >
          <View className="mb-6 h-[27px] w-[84px]">
            <View className="absolute inset-0 right-[70.6%]">
              <Image
                source={require("@/assets/icons/login/postiz-mark.svg")}
                className="w-[25px] h-[27px]"
                contentFit="contain"
              />
            </View>
            <View className="absolute top-[1.61%] bottom-[10.76%] left-[37.32%] right-0">
              <Image
                source={require("@/assets/icons/login/postiz-wordmark.svg")}
                className="w-[53px] h-[24px]"
                contentFit="contain"
              />
            </View>
          </View>

          <View className="gap-5">
            <View className="relative gap-6">
              <Text className="font-jakarta text-2xl font-semibold leading-8 text-text-primary">
                Sign Up
              </Text>
              <View
                pointerEvents="none"
                className="absolute top-7 z-20 left-[-8.25px]"
              >
                <Image
                  source={require("@/assets/icons/login/signup-doodle.svg")}
                  className="w-[153px] h-[13px]"
                  contentFit="contain"
                />
              </View>

              <View className="gap-5 pt-[7px]">
                <View className="gap-3">
                  <Text className="font-jakarta text-sm text-text-secondary">
                    Continue with
                  </Text>
                  <View className="flex-row gap-2">
                    <Pressable className="h-[52px] flex-1 items-center justify-center rounded-[10px] bg-white">
                      <Image
                        source={require("@/assets/icons/login/google.svg")}
                        className="w-6 h-6"
                        contentFit="contain"
                      />
                    </Pressable>
                    <Pressable className="h-[52px] flex-1 items-center justify-center rounded-[10px] bg-white">
                      <Image
                        source={require("@/assets/icons/login/apple.svg")}
                        className="w-6 h-6"
                        contentFit="contain"
                      />
                    </Pressable>
                    <Pressable className="h-[52px] flex-1 items-center justify-center rounded-[10px] bg-white">
                      <Image
                        source={require("@/assets/icons/login/wallet.svg")}
                        className="w-6 h-6"
                        contentFit="contain"
                      />
                    </Pressable>
                  </View>
                </View>

                <View className="flex-row items-center justify-center gap-5">
                  <View className="h-px w-[100px] bg-separator-primary" />
                  <Text className="font-jakarta text-sm text-text-secondary">
                    or
                  </Text>
                  <View className="h-px w-[100px] bg-separator-primary" />
                </View>

                <AuthInput
                  label="Email"
                  value={email}
                  onChangeText={(text) => {
                    setEmail(text);
                    if (errors.email)
                      setErrors((prev) => ({ ...prev, email: undefined }));
                  }}
                  placeholder="Enter email address"
                  keyboardType="email-address"
                  autoCapitalize="none"
                  error={!!errors.email}
                  hint={errors.email}
                />

                <AuthInput
                  ref={passwordInputRef}
                  label="Password"
                  value={password}
                  onChangeText={(text) => {
